CREATE TABLE IF NOT EXISTS apps (id TEXT PRIMARY KEY, publisher_id TEXT NOT NULL REFERENCES publishers(id), app_namespace TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(publisher_id,app_namespace));
CREATE TABLE IF NOT EXISTS app_versions (package_digest TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES apps(id), semver TEXT NOT NULL, manifest_json TEXT NOT NULL, artifact_digest TEXT NOT NULL, total_bytes INTEGER NOT NULL CHECK(total_bytes BETWEEN 100 AND 8192), r2_key TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('PENDING','ACTIVE')), UNIQUE(app_id,semver));
